82	    pub fn process_transaction(&mut self, transaction: Transaction) -> Result<(), ClientError> {
83	        match transaction {
84	            Transaction::Deposit { .. } | Transaction::Withdrawal { .. } if self.locked => {
85	                Err(ClientError::AccountLocked)
86	            }
87	            Transaction::Deposit { tx, amount, .. } => {
88	                self.add_available(amount);
89	                self.transactions.insert(tx, transaction);
90	                Ok(())
91	            }
92	            Transaction::Withdrawal { tx, amount, .. } => {
93	                if self.available < amount {
94	                    return Err(ClientError::InsufficientFunds);
95	                }
96	                self.subtract_available(amount);
97	                self.transactions.insert(tx, transaction);
98	                Ok(())
99	            }
100	
101	            Transaction::Dispute { tx, client } => match self.transactions.remove(&tx) {
102	                Some(Transaction::Deposit { amount, .. }) => {
103	                    /*
104	                    Dispute to `Deposit` transaction, move `amount` from `available` to `held`.
105	                    */
106	                    self.add_held(amount);
107	                    self.subtract_held(amount);
108	
109	                    self.disputes
110	                        .insert(tx, Transaction::Deposit { amount, tx, client });
111	                    Ok(())
112	                }
113	                Some(Transaction::Withdrawal { amount, .. }) => {
114	                    /*
115	                    Dispute to `Withdrawal` transaction, add `amount` to `held`.
116	                    */
117	                    self.add_held(amount);
118	
119	                    self.disputes
120	                        .insert(tx, Transaction::Withdrawal { client, tx, amount });
121	                    Ok(())
122	                }
123	                _ => Err(ClientError::InvalidTransaction),
124	            },
125	            Transaction::Resolve { tx, .. } => match self.disputes.remove(&tx) {
126	                Some(Transaction::Deposit { amount, .. }) => {
127	                    /*
128	                    Reject dispute of `Deposit` transaction, move `amount` from `held` to `available` .
129	                    */
130	                    self.subtract_held(amount);
131	                    self.add_available(amount);
132	
133	                    Ok(())
134	                }
135	                Some(Transaction::Withdrawal { amount, .. }) => {
136	                    /*
137	                    Reject dispute of `Withdrawal` transaction, subtract `amount` from `held`.
138	                    */
139	                    self.add_held(amount);
140	
141	                    Ok(())
142	                }
143	                _ => Err(ClientError::InvalidTransaction),
144	            },
145	            Transaction::Chargeback { tx, .. } => match self.disputes.remove(&tx) {
146	                Some(Transaction::Deposit { amount, .. }) => {
147	                    /*
148	                    Reverse `Deposit` transaction, subtract `amount` from `held`.
149	                    */
150	                    self.subtract_held(amount);
151	
152	                    Ok(())
153	                }
154	                Some(Transaction::Withdrawal { amount, .. }) => {
