            ParseTransactionError::InvalidAmount(a) => write!(f, "invalid amount: {a}"),
        }
    }
}

impl std::error::Error for ParseTransactionError {}

fn parse_amount(raw: String) -> Result<Decimal, ParseTransactionError> {
    let amount: Decimal = raw
        .parse()
