9	#[derive(Debug)]
10	pub enum ClientError {
11	    AccountLocked,
12	    InsufficientFunds,
13	    InvalidTransaction,
14	}
15	
16	impl fmt::Display for ClientError {
17	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
18	        match self {
19	            ClientError::AccountLocked => write!(f, "account is locked"),
20	            ClientError::InsufficientFunds => write!(f, "insufficient available funds"),
21	            ClientError::InvalidTransaction => write!(f, "invalid transaction"),
22	        }
23	    }
24	}
25	
26	impl std::error::Error for ClientError {}
27	
28	pub struct Client {
29	    pub client_id: u16,
30	    pub available: Decimal,
31	    pub held: Decimal,
32	    pub locked: bool,
33	    // holds `Deposit` and `Withdrawal` transaction history
34	    pub transactions: HashMap<u32, Transaction>,
35	    // holds disputed `Deposit` and `Withdrawal` transactions
36	    pub disputes: HashMap<u32, Transaction>,
37	}
38	
39	impl Serialize for Client {
40	    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
41	    where
42	        S: Serializer,
43	    {
44	        let mut state = serializer.serialize_struct("Client", 5)?;
45	        state.serialize_field("client", &self.client_id)?;
46	        state.serialize_field("available", &self.available)?;
47	        state.serialize_field("held", &self.held)?;
48	        state.serialize_field("total", &(self.available + self.held))?;
49	        state.serialize_field("locked", &self.locked)?;
50	        state.end()
51	    }
52	}
53	
54	impl Client {
55	    pub fn new(client_id: u16) -> Self {
56	        Client {
57	            client_id,
58	            available: Decimal::ZERO,
59	            held: Decimal::ZERO,
60	            locked: false,
61	            transactions: HashMap::new(),
62	            disputes: HashMap::new(),
63	        }
64	    }
65	
66	    fn add_available(&mut self, amount: Decimal) {
67	        self.available = (self.available + amount).round_dp(4);
68	    }
69	
70	    fn subtract_available(&mut self, amount: Decimal) {
71	        self.available = (self.available - amount).round_dp(4);
72	    }
73	
74	    fn add_held(&mut self, amount: Decimal) {
75	        self.held = (self.held + amount).round_dp(4);
76	    }
77	
78	    fn subtract_held(&mut self, amount: Decimal) {
79	        self.held = (self.held - amount).round_dp(4);
80	    }
81	
82	    pub fn process_transaction(&mut self, transaction: Transaction) -> Result<(), ClientError> {
83	        match transaction {
84	            Transaction::Deposit { .. } | Transaction::Withdrawal { .. } if self.locked => {
85	                Err(ClientError::AccountLocked)
86	            }
87	            Transaction::Deposit { tx, amount, .. } => {
88	                self.add_available(amount);
89	                self.transactions.insert(tx, transaction);
90	                Ok(())
91	            }
92	            Transaction::Withdrawal { tx, amount, .. } => {
93	                if self.available < amount {
94	                    return Err(ClientError::InsufficientFunds);
95	                }
96	                self.subtract_available(amount);
97	                self.transactions.insert(tx, transaction);
98	                Ok(())
99	            }
100	
101	            Transaction::Dispute { tx, client } => match self.transactions.remove(&tx) {
102	                Some(Transaction::Deposit { amount, .. }) => {
103	                    /*
104	                    Dispute to `Deposit` transaction, move `amount` from `available` to `held`.
105	                    */
106	                    self.add_held(amount);
107	                    self.subtract_held(amount);
