9	// Subset of `Transaction` holding only the funds-moving variants, used to
10	// remember transaction history for `Dispute`/`Resolve`/`Chargeback` lookups.
11	// Internal to `Client` — never exposed outside this module.
12	#[derive(Debug)]
13	enum FundsTransaction {
14	    Deposit { amount: Decimal },
15	    Withdrawal { amount: Decimal },
16	}
