25	impl fmt::Display for ClientError {
26	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
27	        match self {
28	            ClientError::AccountLocked => write!(f, "account is locked"),
29	            ClientError::InsufficientFunds => write!(f, "insufficient available funds"),
30	            ClientError::InvalidTransaction => write!(f, "invalid transaction"),
31	        }
32	    }
33	}
