37	pub struct Client {
38	    pub client_id: u16,
39	    pub available: Decimal,
40	    pub held: Decimal,
41	    pub locked: bool,
42	    // holds `Deposit` and `Withdrawal` transaction history
43	    transactions: HashMap<u32, FundsTransaction>,
44	    // holds disputed `Deposit` and `Withdrawal` transactions
45	    disputes: HashMap<u32, FundsTransaction>,
46	}
47	
48	impl Serialize for Client {
49	    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
50	    where
51	        S: Serializer,
52	    {
53	        let mut state = serializer.serialize_struct("Client", 5)?;
54	        state.serialize_field("client", &self.client_id)?;
55	        state.serialize_field("available", &self.available)?;
56	        state.serialize_field("held", &self.held)?;
57	        state.serialize_field("total", &(self.available + self.held))?;
58	        state.serialize_field("locked", &self.locked)?;
59	        state.end()
60	    }
61	}
62	
63	impl Client {
64	    pub fn new(client_id: u16) -> Self {
65	        Client {
66	            client_id,
67	            available: Decimal::ZERO,
68	            held: Decimal::ZERO,
69	            locked: false,
70	            transactions: HashMap::new(),
71	            disputes: HashMap::new(),
72	        }
73	    }
74	
75	    fn add_available(&mut self, amount: &Decimal) {
76	        self.available = (self.available + amount).round_dp(4);
77	    }
78	
79	    fn subtract_available(&mut self, amount: &Decimal) {
80	        self.available = (self.available - amount).round_dp(4);
81	    }
82	
83	    fn add_held(&mut self, amount: &Decimal) {
84	        self.held = (self.held + amount).round_dp(4);
85	    }
86	
87	    fn subtract_held(&mut self, amount: &Decimal) {
88	        self.held = (self.held - amount).round_dp(4);
89	    }
