91	    pub fn process_transaction(&mut self, transaction: Transaction) -> Result<(), ClientError> {
92	        match transaction {
93	            Transaction::Deposit { .. } | Transaction::Withdrawal { .. } if self.locked => {
94	                Err(ClientError::AccountLocked)
95	            }
96	            Transaction::Deposit { tx, amount, .. } => {
97	                self.add_available(&amount);
98	                self.transactions
99	                    .insert(tx, FundsTransaction::Deposit { amount });
100	                Ok(())
101	            }
102	            Transaction::Withdrawal { tx, amount, .. } => {
103	                if self.available < amount {
104	                    return Err(ClientError::InsufficientFunds);
105	                }
106	                self.subtract_available(&amount);
107	                self.transactions
108	                    .insert(tx, FundsTransaction::Withdrawal { amount });
109	                Ok(())
110	            }
111	
112	            Transaction::Dispute { tx, .. } => match self.transactions.remove(&tx) {
113	                Some(FundsTransaction::Deposit { amount }) => {
114	                    /*
115	                    Dispute to `Deposit` transaction, move `amount` from `available` to `held`.
116	                    */
117	                    self.add_held(&amount);
118	                    self.subtract_held(&amount);
119	
120	                    self.disputes
121	                        .insert(tx, FundsTransaction::Deposit { amount });
122	                    Ok(())
123	                }
124	                Some(FundsTransaction::Withdrawal { amount }) => {
125	                    /*
126	                    Dispute to `Withdrawal` transaction, add `amount` to `held`.
127	                    */
128	                    self.add_held(&amount);
129	
130	                    self.disputes
131	                        .insert(tx, FundsTransaction::Withdrawal { amount });
132	                    Ok(())
133	                }
134	                None => Err(ClientError::InvalidTransaction),
135	            },
136	            Transaction::Resolve { tx, .. } => match self.disputes.remove(&tx) {
137	                Some(FundsTransaction::Deposit { amount }) => {
138	                    /*
139	                    Reject dispute of `Deposit` transaction, move `amount` from `held` to `available` .
140	                    */
141	                    self.subtract_held(&amount);
142	                    self.add_available(&amount);
143	
144	                    Ok(())
145	                }
146	                Some(FundsTransaction::Withdrawal { amount }) => {
147	                    /*
148	                    Reject dispute of `Withdrawal` transaction, subtract `amount` from `held`.
149	                    */
150	                    self.add_held(&amount);
151	
152	                    Ok(())
153	                }
154	                None => Err(ClientError::InvalidTransaction),
155	            },
156	            Transaction::Chargeback { tx, .. } => match self.disputes.remove(&tx) {
157	                Some(FundsTransaction::Deposit { amount }) => {
158	                    /*
159	                    Reverse `Deposit` transaction, subtract `amount` from `held`.
160	                    */
161	                    self.subtract_held(&amount);
162	
163	                    Ok(())
164	                }
165	                Some(FundsTransaction::Withdrawal { amount }) => {
166	                    /*
167	                    Reverse of `Withdrawal` transaction, move `amount` from `held` to `available`.
168	                    */
169	                    self.subtract_held(&amount);
170	                    self.add_available(&amount);
171	
172	                    Ok(())
173	                }
174	                None => Err(ClientError::InvalidTransaction),
175	            },
176	        }
177	    }
178	}

