use std::convert::TryFrom;
use std::fmt;

use rust_decimal::Decimal;

use crate::record::Record;

#[derive(Debug)]
pub enum Transaction {
    Deposit {
        client: u16,
        tx: u32,
        amount: Decimal,
    },
    Withdrawal {
        client: u16,
        tx: u32,
        amount: Decimal,
    },
    Dispute {
        client: u16,
        tx: u32,
    },
    Resolve {
        client: u16,
        tx: u32,
    },
    Chargeback {
        client: u16,
        tx: u32,
    },
}

impl Transaction {
    pub fn client_id(&self) -> u16 {
        match self {
            Transaction::Deposit { client, .. }
            | Transaction::Withdrawal { client, .. }
            | Transaction::Dispute { client, .. }
            | Transaction::Resolve { client, .. }
            | Transaction::Chargeback { client, .. } => *client,
        }
    }
}

#[derive(Debug)]
pub enum ParseTransactionError {
    UnknownType(String),
    InvalidAmount(String),
}

impl fmt::Display for ParseTransactionError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseTransactionError::UnknownType(t) => write!(f, "unknown transaction type: {t}"),
            ParseTransactionError::InvalidAmount(a) => write!(f, "invalid amount: {a}"),
        }
    }
}

impl std::error::Error for ParseTransactionError {}

fn parse_amount(raw: String) -> Result<Decimal, ParseTransactionError> {
    let amount: Decimal = raw
        .parse()
        .map_err(|_| ParseTransactionError::InvalidAmount(raw.clone()))?;
    if !amount.is_sign_positive() {
        return Err(ParseTransactionError::InvalidAmount(raw));
    }
    Ok(amount)
}

impl TryFrom<Record> for Transaction {
    type Error = ParseTransactionError;

    fn try_from(record: Record) -> Result<Self, Self::Error> {
        match record.r#type.as_str() {
            "deposit" => Ok(Transaction::Deposit {
                client: record.client,
                tx: record.tx,
                amount: parse_amount(record.amount)?,
            }),
            "withdrawal" => Ok(Transaction::Withdrawal {
                client: record.client,
                tx: record.tx,
                amount: parse_amount(record.amount)?,
            }),
            "dispute" => Ok(Transaction::Dispute {
                client: record.client,
                tx: record.tx,
            }),
            "resolve" => Ok(Transaction::Resolve {
                client: record.client,
                tx: record.tx,
            }),
            "chargeback" => Ok(Transaction::Chargeback {
                client: record.client,
                tx: record.tx,
            }),
            other => Err(ParseTransactionError::UnknownType(other.to_string())),
        }
    }
}

mod client;
mod engine;
mod record;
mod transaction;

use std::collections::HashMap;
use std::env;
use std::error::Error;
use std::fs::File;
use std::io;
use std::path::Path;
use std::process::ExitCode;

use record::Record;

use crate::client::Client;
use crate::engine::TransactionEngine;
use crate::transaction::Transaction;

fn load_records(path: &str) -> Result<csv::DeserializeRecordsIntoIter<File, Record>, csv::Error> {
    let reader = csv::ReaderBuilder::new()
        // remove extra whitespaces from input file
        .trim(csv::Trim::All)
        .from_path(path)?;
    Ok(reader.into_deserialize())
}

fn write_clients(clients: &HashMap<u16, Client>) -> Result<(), Box<dyn Error>> {
    let mut writer = csv::Writer::from_writer(io::stdout());
    for client in clients.values() {
        writer.serialize(client)?;
    }
    writer.flush()?;
    Ok(())
}

fn print_usage(program: &str) {
    eprintln!("Usage: {program} <input.csv>");
    eprintln!("  <input.csv>    path to a CSV file containing transactions");
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        print_usage(&args[0]);
        return ExitCode::FAILURE;
    }

    let path = &args[1];
    if !Path::new(path).exists() {
        eprintln!("error: file '{path}' does not exist");
        return ExitCode::FAILURE;
    }

    let records = match load_records(path) {
        Ok(records) => records,
        Err(e) => {
            eprintln!("error: failed to parse CSV file '{path}': {e}");
            return ExitCode::FAILURE;
        }
    };

    let mut engine = TransactionEngine::new();

    for record in records {
        let record = match record {
            Ok(r) => r,
            Err(e) => {
                eprintln!("error: failed to parse CSV file '{path}': {e}");
                continue;
            }
        };
        let transanction = match Transaction::try_from(record) {
            Ok(v) => v,
            Err(e) => {
                // ignore invalid records
                eprintln!("error: cannot parse record '{record}': {e}");
                continue;
            }
        };
        let res = engine.process_transaction(transanction);
        if let Err(e) = res {
            eprintln!("{e:?}");
        }
    }

    if let Err(e) = write_clients(&engine.clients) {
        eprintln!("error: failed to write CSV output: {e}");
        return ExitCode::FAILURE;
    }

    ExitCode::SUCCESS
}

