1	use std::collections::{HashMap, HashSet};
2	use std::fmt;
3	
4	use rust_decimal::Decimal;
5	use serde::ser::{Serialize, SerializeStruct, Serializer};
6	
7	use crate::transaction::Transaction;
8	
9	// Subset of `Transaction` holding only the funds-moving variants, used to
10	// remember transaction history for `Dispute`/`Resolve`/`Chargeback` lookups.
11	// Internal to `Client` — never exposed outside this module.
12	#[derive(Debug)]
13	enum FundsTransaction {
14	    Deposit { amount: Decimal },
15	    Withdrawal { amount: Decimal },
16	}
17	
18	#[derive(Debug)]
19	pub enum ClientError {
20	    AccountLocked,
21	    InsufficientFunds,
22	    InvalidTransaction,
23	    TransactionReferenceConflict,
24	}
25	
26	impl fmt::Display for ClientError {
27	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
28	        match self {
29	            ClientError::AccountLocked => write!(f, "account is locked"),
30	            ClientError::InsufficientFunds => write!(f, "insufficient available funds"),
31	            ClientError::InvalidTransaction => write!(f, "invalid transaction"),
32	            ClientError::TransactionReferenceConflict => {
33	                write!(f, "transaction identifier conflict")
34	            }
35	        }
36	    }
37	}
38	
39	impl std::error::Error for ClientError {}
40	
41	pub struct Client {
42	    pub client_id: u16,
43	    pub available: Decimal,
44	    pub held: Decimal,
45	    pub locked: bool,
46	    // holds `Deposit` and `Withdrawal` transaction history
47	    transactions: HashMap<u32, FundsTransaction>,
48	    // holds disputed `Deposit` and `Withdrawal` transactions
49	    disputes: HashMap<u32, FundsTransaction>,
50	    // holds resolved or chargebacked txs to detect tx conflict
51	    handled_disputes: HashSet<u32>,
52	}
53	
54	impl Serialize for Client {
55	    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
56	    where
57	        S: Serializer,
58	    {
59	        let mut state = serializer.serialize_struct("Client", 5)?;
60	        state.serialize_field("client", &self.client_id)?;
61	        state.serialize_field("available", &self.available)?;
62	        state.serialize_field("held", &self.held)?;
63	        state.serialize_field("total", &(self.available + self.held))?;
64	        state.serialize_field("locked", &self.locked)?;
65	        state.end()
66	    }
67	}
68	
69	impl Client {
70	    pub fn new(client_id: u16) -> Self {
71	        Client {
72	            client_id,
73	            available: Decimal::ZERO,
74	            held: Decimal::ZERO,
75	            locked: false,
76	            transactions: HashMap::new(),
77	            disputes: HashMap::new(),
78	            handled_disputes: HashSet::new(),
79	        }
80	    }
81	
82	    fn add_available(&mut self, amount: &Decimal) {
83	        self.available = (self.available + amount).round_dp(4);
84	    }
85	
86	    fn subtract_available(&mut self, amount: &Decimal) {
87	        self.available = (self.available - amount).round_dp(4);
88	    }
89	
90	    fn add_held(&mut self, amount: &Decimal) {
91	        self.held = (self.held + amount).round_dp(4);
92	    }
93	
94	    fn subtract_held(&mut self, amount: &Decimal) {
95	        self.held = (self.held - amount).round_dp(4);
96	    }
97	
98	    fn is_tx_in_conflict(&self, tx: &u32) -> bool {
99	        self.transactions.contains_key(&tx)
100	            || self.disputes.contains_key(&tx)
101	            || self.handled_disputes.contains(&tx)
102	    }
103	
104	    pub fn process_transaction(&mut self, transaction: Transaction) -> Result<(), ClientError> {
105	        match transaction {
106	            Transaction::Deposit { .. } | Transaction::Withdrawal { .. } if self.locked => {
107	                /*
108	                Client has locked account.
109	                */
110	                Err(ClientError::AccountLocked)
111	            }
112	            Transaction::Deposit { tx, .. } | Transaction::Withdrawal { tx, .. }
113	                if self.is_tx_in_conflict(&tx) =>
114	            {
115	                /*
116	                Transaction identifier detected.
117	                */
118	                Err(ClientError::TransactionReferenceConflict)
119	            }
120	            Transaction::Withdrawal { amount, .. } if self.available < amount => {
121	                /*
122	                Client has no funds for withdrawal.
123	                */
124	                Err(ClientError::InsufficientFunds)
125	            }
126	            Transaction::Deposit { tx, amount, .. } => {
127	                /*
128	                Add `amount` to available deposit.
129	                */
130	                self.add_available(&amount);
131	                self.transactions
132	                    .insert(tx, FundsTransaction::Deposit { amount });
133	                Ok(())
134	            }
135	
136	            Transaction::Withdrawal { tx, amount, .. } => {
137	                /*
138	                Withdraw `amount` from available deposit.
139	                */
140	                self.subtract_available(&amount);
141	                self.transactions
142	                    .insert(tx, FundsTransaction::Withdrawal { amount });
143	                Ok(())
144	            }
145	
146	            Transaction::Dispute { tx, .. } => match self.transactions.remove(&tx) {
147	                Some(FundsTransaction::Deposit { amount }) => {
148	                    /*
149	                    Dispute to `Deposit` transaction, move `amount` from `available` to `held`.
150	                    */
151	                    self.add_held(&amount);
152	                    self.subtract_available(&amount);
153	
154	                    self.disputes
155	                        .insert(tx, FundsTransaction::Deposit { amount });
156	                    Ok(())
157	                }
158	                Some(FundsTransaction::Withdrawal { amount }) => {
159	                    /*
160	                    Dispute to `Withdrawal` transaction, add `amount` to `held`.
161	                    */
162	                    self.add_held(&amount);
163	
164	                    self.disputes
165	                        .insert(tx, FundsTransaction::Withdrawal { amount });
166	                    Ok(())
167	                }
168	                None => Err(ClientError::InvalidTransaction),
169	            },
170	            Transaction::Resolve { tx, .. } => match self.disputes.remove(&tx) {
171	                Some(FundsTransaction::Deposit { amount }) => {
172	                    /*
173	                    Reject dispute of `Deposit` transaction, move `amount` from `held` to `available` .
174	                    */
175	                    self.subtract_held(&amount);
176	                    self.add_available(&amount);
177	                    self.handled_disputes.insert(tx);
178	
179	                    Ok(())
180	                }
181	                Some(FundsTransaction::Withdrawal { amount }) => {
182	                    /*
183	                    Reject dispute of `Withdrawal` transaction, subtract `amount` from `held`.
184	                    */
185	                    self.subtract_held(&amount);
186	                    self.handled_disputes.insert(tx);
187	
188	                    Ok(())
189	                }
190	                None => Err(ClientError::InvalidTransaction),
191	            },
192	            Transaction::Chargeback { tx, .. } => match self.disputes.remove(&tx) {
193	                Some(FundsTransaction::Deposit { amount }) => {
194	                    /*
195	                    Reverse `Deposit` transaction, subtract `amount` from `held`.
196	                    */
197	                    self.subtract_held(&amount);
198	                    self.handled_disputes.insert(tx);
199	                    self.locked = true;
200	
201	                    Ok(())
202	                }
203	                Some(FundsTransaction::Withdrawal { amount }) => {
204	                    /*
205	                    Reverse of `Withdrawal` transaction, move `amount` from `held` to `available`.
206	                    */
207	                    self.subtract_held(&amount);
208	                    self.add_available(&amount);
209	                    self.handled_disputes.insert(tx);
210	                    self.locked = true;
211	
212	                    Ok(())
213	                }
214	                None => Err(ClientError::InvalidTransaction),
215	            },
216	        }
217	    }
218	}
