use std::collections::{HashMap, HashSet};
use std::fmt;

use rust_decimal::Decimal;
use serde::ser::{Serialize, SerializeStruct, Serializer};

use crate::transaction::Transaction;

// Subset of `Transaction` holding only the funds-moving variants, used to
// remember transaction history for `Dispute`/`Resolve`/`Chargeback` lookups.
// Internal to `Client` — never exposed outside this module.
#[derive(Debug)]
enum FundsTransaction {
    Deposit { amount: Decimal },
    Withdrawal { amount: Decimal },
}

#[derive(Debug)]
pub enum ClientError {
    AccountLocked,
    InsufficientFunds,
    InvalidTransaction,
    TransactionReferenceConflict,
}

impl fmt::Display for ClientError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ClientError::AccountLocked => write!(f, "account is locked"),
            ClientError::InsufficientFunds => write!(f, "insufficient available funds"),
            ClientError::InvalidTransaction => write!(f, "invalid transaction"),
            ClientError::TransactionReferenceConflict => {
                write!(f, "transaction identifier conflict")
            }
        }
    }
}

impl std::error::Error for ClientError {}

pub struct Client {
    pub client_id: u16,
    pub available: Decimal,
    pub held: Decimal,
    pub locked: bool,
    // holds `Deposit` and `Withdrawal` transaction history
    transactions: HashMap<u32, FundsTransaction>,
    // holds disputed `Deposit` and `Withdrawal` transactions
    disputes: HashMap<u32, FundsTransaction>,
    // holds resolved or chargebacked txs to detect tx conflict
    handled_disputes: HashSet<u32>,
}

impl Serialize for Client {
    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
    where
        S: Serializer,
    {
        let mut state = serializer.serialize_struct("Client", 5)?;
        state.serialize_field("client", &self.client_id)?;
        state.serialize_field("available", &self.available)?;
        state.serialize_field("held", &self.held)?;
        state.serialize_field("total", &(self.available + self.held))?;
        state.serialize_field("locked", &self.locked)?;
        state.end()
    }
}

impl Client {
    pub fn new(client_id: u16) -> Self {
        Client {
            client_id,
            available: Decimal::ZERO,
            held: Decimal::ZERO,
            locked: false,
            transactions: HashMap::new(),
            disputes: HashMap::new(),
            handled_disputes: HashSet::new(),
        }
    }

    fn add_available(&mut self, amount: &Decimal) {
        self.available = (self.available + amount).round_dp(4);
    }

    fn subtract_available(&mut self, amount: &Decimal) {
        self.available = (self.available - amount).round_dp(4);
    }

    fn add_held(&mut self, amount: &Decimal) {
        self.held = (self.held + amount).round_dp(4);
    }

    fn subtract_held(&mut self, amount: &Decimal) {
        self.held = (self.held - amount).round_dp(4);
    }

    fn is_tx_in_conflict(&self, tx: &u32) -> bool {
        self.transactions.contains_key(&tx)
            || self.disputes.contains_key(&tx)
            || self.handled_disputes.contains(&tx)
    }

    pub fn process_transaction(&mut self, transaction: Transaction) -> Result<(), ClientError> {
        match transaction {
            Transaction::Deposit { .. } | Transaction::Withdrawal { .. } if self.locked => {
                /*
                Client has locked account.
                */
                Err(ClientError::AccountLocked)
            }
            Transaction::Deposit { tx, .. } | Transaction::Withdrawal { tx, .. }
                if self.is_tx_in_conflict(&tx) =>
            {
                /*
                Transaction identifier detected.
                */
                Err(ClientError::TransactionReferenceConflict)
            }
            Transaction::Withdrawal { amount, .. } if self.available < amount => {
                /*
                Client has no funds for withdrawal.
                */
                Err(ClientError::InsufficientFunds)
            }
            Transaction::Deposit { tx, amount, .. } => {
                /*
                Add `amount` to available deposit.
                */
                self.add_available(&amount);
                self.transactions
                    .insert(tx, FundsTransaction::Deposit { amount });
                Ok(())
            }

            Transaction::Withdrawal { tx, amount, .. } => {
                /*
                Withdraw `amount` from available deposit.
                */
                self.subtract_available(&amount);
                self.transactions
                    .insert(tx, FundsTransaction::Withdrawal { amount });
                Ok(())
            }

            Transaction::Dispute { tx, .. } => match self.transactions.remove(&tx) {
                Some(FundsTransaction::Deposit { amount }) => {
                    /*
                    Dispute to `Deposit` transaction, move `amount` from `available` to `held`.
                    */
                    self.add_held(&amount);
                    self.subtract_available(&amount);

                    self.disputes
                        .insert(tx, FundsTransaction::Deposit { amount });
                    Ok(())
                }
                Some(FundsTransaction::Withdrawal { amount }) => {
                    /*
                    Dispute to `Withdrawal` transaction, add `amount` to `held`.
                    */
                    self.add_held(&amount);

                    self.disputes
                        .insert(tx, FundsTransaction::Withdrawal { amount });
                    Ok(())
                }
                None => Err(ClientError::InvalidTransaction),
            },
            Transaction::Resolve { tx, .. } => match self.disputes.remove(&tx) {
                Some(FundsTransaction::Deposit { amount }) => {
                    /*
                    Reject dispute of `Deposit` transaction, move `amount` from `held` to `available` .
                    */
                    self.subtract_held(&amount);
                    self.add_available(&amount);
                    self.handled_disputes.insert(tx);

                    Ok(())
                }
                Some(FundsTransaction::Withdrawal { amount }) => {
                    /*
                    Reject dispute of `Withdrawal` transaction, subtract `amount` from `held`.
                    */
                    self.subtract_held(&amount);
                    self.handled_disputes.insert(tx);

                    Ok(())
                }
                None => Err(ClientError::InvalidTransaction),
            },
            Transaction::Chargeback { tx, .. } => match self.disputes.remove(&tx) {
                Some(FundsTransaction::Deposit { amount }) => {
                    /*
                    Reverse `Deposit` transaction, subtract `amount` from `held`.
                    */
                    self.subtract_held(&amount);
                    self.handled_disputes.insert(tx);
                    self.locked = true;

                    Ok(())
                }
                Some(FundsTransaction::Withdrawal { amount }) => {
                    /*
                    Reverse of `Withdrawal` transaction, move `amount` from `held` to `available`.
                    */
                    self.subtract_held(&amount);
                    self.add_available(&amount);
                    self.handled_disputes.insert(tx);
                    self.locked = true;

                    Ok(())
                }
                None => Err(ClientError::InvalidTransaction),
            },
        }
    }
}

#[cfg(test)]
mod tests {
    use rust_decimal_macros::dec;

    use super::*;

    fn deposit(client: u16, tx: u32, amount: Decimal) -> Transaction {
        Transaction::Deposit { client, tx, amount }
    }

    fn withdrawal(client: u16, tx: u32, amount: Decimal) -> Transaction {
        Transaction::Withdrawal { client, tx, amount }
    }

    fn dispute(client: u16, tx: u32) -> Transaction {
        Transaction::Dispute { client, tx }
    }

    fn resolve(client: u16, tx: u32) -> Transaction {
        Transaction::Resolve { client, tx }
    }

    fn chargeback(client: u16, tx: u32) -> Transaction {
        Transaction::Chargeback { client, tx }
    }

    #[test]
    fn several_deposits_accumulate_for_single_client() {
        let mut client = Client::new(1);
        client
            .process_transaction(deposit(1, 1, dec!(1.0)))
            .unwrap();
        client
            .process_transaction(deposit(1, 2, dec!(2.5)))
            .unwrap();
        client
            .process_transaction(deposit(1, 3, dec!(0.2500)))
            .unwrap();
        assert_eq!(client.available, dec!(3.7500));
        assert_eq!(client.held, Decimal::ZERO);
        assert!(!client.locked);
    }

    #[test]
    fn new_client_has_zeroed_state() {
        let client = Client::new(1);
        assert_eq!(client.client_id, 1);
        assert_eq!(client.available, Decimal::ZERO);
        assert_eq!(client.held, Decimal::ZERO);
        assert!(!client.locked);
    }

    #[test]
    fn deposit_increases_available() {
        let mut client = Client::new(1);
        client.process_transaction(deposit(1, 1, dec!(1.5))).unwrap();
        assert_eq!(client.available, dec!(1.5));
        assert_eq!(client.held, Decimal::ZERO);
    }

    #[test]
    fn withdrawal_decreases_available() {
        let mut client = Client::new(1);
        client
            .process_transaction(deposit(1, 1, dec!(2.0)))
            .unwrap();
        client
            .process_transaction(withdrawal(1, 2, dec!(0.5)))
            .unwrap();
        assert_eq!(client.available, dec!(1.5));
    }

    #[test]
    fn withdrawal_fails_with_insufficient_funds() {
        let mut client = Client::new(1);
        let result = client.process_transaction(withdrawal(1, 1, dec!(1.0)));
        assert!(matches!(result, Err(ClientError::InsufficientFunds)));
        assert_eq!(client.available, Decimal::ZERO);
    }

    #[test]
    fn deposit_rejected_when_locked() {
        let mut client = Client::new(1);
        client.locked = true;
        let result = client.process_transaction(deposit(1, 1, dec!(1.0)));
        assert!(matches!(result, Err(ClientError::AccountLocked)));
        assert_eq!(client.available, Decimal::ZERO);
    }

    #[test]
    fn duplicate_tx_id_is_rejected() {
        let mut client = Client::new(1);
        client
            .process_transaction(deposit(1, 1, dec!(1.0)))
            .unwrap();
        let result = client.process_transaction(deposit(1, 1, dec!(2.0)));
        assert!(matches!(
            result,
            Err(ClientError::TransactionReferenceConflict)
        ));
        assert_eq!(client.available, dec!(1.0));
    }

    #[test]
    fn dispute_deposit_moves_funds_to_held() {
        let mut client = Client::new(1);
        client
            .process_transaction(deposit(1, 1, dec!(1.0)))
            .unwrap();
        client.process_transaction(dispute(1, 1)).unwrap();
        assert_eq!(client.available, Decimal::ZERO);
        assert_eq!(client.held, dec!(1.0));
    }

    #[test]
    fn dispute_withdrawal_holds_amount_without_touching_available() {
        let mut client = Client::new(1);
        client
            .process_transaction(deposit(1, 1, dec!(5.0)))
            .unwrap();
        client
            .process_transaction(withdrawal(1, 2, dec!(2.0)))
            .unwrap();
        client.process_transaction(dispute(1, 2)).unwrap();
        assert_eq!(client.available, dec!(3.0));
        assert_eq!(client.held, dec!(2.0));
    }

    #[test]
    fn dispute_unknown_tx_is_invalid() {
        let mut client = Client::new(1);
        let result = client.process_transaction(dispute(1, 99));
        assert!(matches!(result, Err(ClientError::InvalidTransaction)));
    }

    #[test]
    fn resolve_deposit_dispute_returns_funds_to_available() {
        let mut client = Client::new(1);
        client
            .process_transaction(deposit(1, 1, dec!(1.0)))
            .unwrap();
        client.process_transaction(dispute(1, 1)).unwrap();
        client.process_transaction(resolve(1, 1)).unwrap();
        assert_eq!(client.available, dec!(1.0));
        assert_eq!(client.held, Decimal::ZERO);
        assert!(!client.locked);
    }

    #[test]
    fn resolve_withdrawal_dispute_releases_held_amount() {
        let mut client = Client::new(1);
        client
            .process_transaction(deposit(1, 1, dec!(5.0)))
            .unwrap();
        client
            .process_transaction(withdrawal(1, 2, dec!(2.0)))
            .unwrap();
        client.process_transaction(dispute(1, 2)).unwrap();
        client.process_transaction(resolve(1, 2)).unwrap();
        assert_eq!(client.available, dec!(3.0));
        assert_eq!(client.held, Decimal::ZERO);
    }

    #[test]
    fn resolve_unknown_tx_is_invalid() {
        let mut client = Client::new(1);
        let result = client.process_transaction(resolve(1, 99));
        assert!(matches!(result, Err(ClientError::InvalidTransaction)));
    }

    #[test]
    fn chargeback_deposit_dispute_locks_account_and_removes_held_funds() {
        let mut client = Client::new(1);
        client
            .process_transaction(deposit(1, 1, dec!(1.0)))
            .unwrap();
        client.process_transaction(dispute(1, 1)).unwrap();
        client.process_transaction(chargeback(1, 1)).unwrap();
        assert_eq!(client.available, Decimal::ZERO);
        assert_eq!(client.held, Decimal::ZERO);
        assert!(client.locked);
    }

    #[test]
    fn chargeback_withdrawal_dispute_locks_account_and_restores_available() {
        let mut client = Client::new(1);
        client
            .process_transaction(deposit(1, 1, dec!(5.0)))
            .unwrap();
        client
            .process_transaction(withdrawal(1, 2, dec!(2.0)))
            .unwrap();
        client.process_transaction(dispute(1, 2)).unwrap();
        client.process_transaction(chargeback(1, 2)).unwrap();
        assert_eq!(client.available, dec!(5.0));
        assert_eq!(client.held, Decimal::ZERO);
        assert!(client.locked);
    }

    #[test]
    fn chargeback_unknown_tx_is_invalid() {
        let mut client = Client::new(1);
        let result = client.process_transaction(chargeback(1, 99));
        assert!(matches!(result, Err(ClientError::InvalidTransaction)));
    }
}

