    29	        client: u16,
    30	        tx: u32,
    31	    },
    32	}
    33	
    34	impl Transaction {
    35	    pub fn client_id(&self) -> u16 {
    36	        match self {
    37	            Transaction::Deposit { client, .. }
    38	            | Transaction::Withdrawal { client, .. }
    39	            | Transaction::Dispute { client, .. }
    40	            | Transaction::Resolve { client, .. }
    41	            | Transaction::Chargeback { client, .. } => *client,
    42	        }
    43	    }
    44	}
    45	
    46	#[derive(Debug)]
    47	pub enum ParseTransactionError {
    48	    UnknownType(String),
    49	    InvalidAmount(String),
    50	}
    51	
    52	impl fmt::Display for ParseTransactionError {
    53	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
    54	        match self {
    55	            ParseTransactionError::UnknownType(t) => write!(f, "unknown transaction type: {t}"),
    56	            ParseTransactionError::InvalidAmount(a) => write!(f, "invalid amount: {a}"),
    57	        }
    58	    }
    59	}
    60	
    61	impl std::error::Error for ParseTransactionError {}
    62	
    63	fn parse_amount(raw: String) -> Result<Decimal, ParseTransactionError> {
    64	    let amount: Decimal = raw
    65	        .parse()
    66	        .map_err(|_| ParseTransactionError::InvalidAmount(raw.clone()))?;
    67	    if !amount.is_sign_positive() || amount.scale() > 4 {
    68	        return Err(ParseTransactionError::InvalidAmount(raw));
    69	    }
    70	    Ok(amount)
    71	}
    72	
    73	impl TryFrom<&Record> for Transaction {
    74	    type Error = ParseTransactionError;
    75	
    76	    fn try_from(record: &Record) -> Result<Self, Self::Error> {
    77	        match record.r#type.as_str() {
    78	            "deposit" => Ok(Transaction::Deposit {
    79	                client: record.client,
    80	                tx: record.tx,
    81	                amount: parse_amount(record.amount.clone())?,
    82	            }),
    83	            "withdrawal" => Ok(Transaction::Withdrawal {
