    86	                amount: parse_amount(record.amount.clone())?,
    87	            }),
    88	            "dispute" => Ok(Transaction::Dispute {
    89	                client: record.client,
    90	                tx: record.tx,
    91	            }),
    92	            "resolve" => Ok(Transaction::Resolve {
    93	                client: record.client,
    94	                tx: record.tx,
    95	            }),
    96	            "chargeback" => Ok(Transaction::Chargeback {
    97	                client: record.client,
    98	                tx: record.tx,
    99	            }),
