   136	            Transaction::Withdrawal { tx, amount, .. } => {
   137	                /*
   138	                Withdraw `amount` from available deposit.
   139	                */
   140	                self.subtract_available(&amount);
   141	                self.transactions
   142	                    .insert(tx, FundsTransaction::Withdrawal { amount });
   143	                Ok(())
   144	            }
