   159	                    /*
   160	                    Dispute to `Withdrawal` transaction, add `amount` to `held`.
   161	                    */
   162	                    self.add_held(&amount);
   163	
   164	                    self.disputes
   165	                        .insert(tx, FundsTransaction::Withdrawal { amount });
   166	                    Ok(())
   167	                }
