   134	            }
   135	
   136	            Transaction::Withdrawal { tx, amount, .. } => {
   137	                /*
   138	                Withdraw `amount` from available deposit.
   139	                */
   140	                self.subtract_available(&amount);
   141	                self.transactions
   142	                    .insert(tx, FundsTransaction::Withdrawal { amount });
   143	                Ok(())
   144	            }
   145	
   146	            Transaction::Dispute { tx, .. } => match self.transactions.remove(&tx) {
   147	                Some(FundsTransaction::Deposit { amount }) => {
   148	                    /*
   149	                    Dispute to `Deposit` transaction, move `amount` from `available` to `held`.
   150	                    */
   151	                    self.add_held(&amount);
   152	                    self.subtract_available(&amount);
   153	
   154	                    self.disputes
   155	                        .insert(tx, FundsTransaction::Deposit { amount });
   156	                    Ok(())
   157	                }
   158	                Some(FundsTransaction::Withdrawal { amount }) => {
   159	                    /*
   160	                    Dispute to `Withdrawal` transaction, add `amount` to `held`.
   161	                    */
   162	                    self.add_held(&amount);
   163	
   164	                    self.disputes
   165	                        .insert(tx, FundsTransaction::Withdrawal { amount });
   166	                    Ok(())
   167	                }
   168	                None => Err(ClientError::InvalidTransaction),
   169	            },
   170	            Transaction::Resolve { tx, .. } => match self.disputes.remove(&tx) {
   171	                Some(FundsTransaction::Deposit { amount }) => {
   172	                    /*
   173	                    Reject dispute of `Deposit` transaction, move `amount` from `held` to `available` .
   174	                    */
   175	                    self.subtract_held(&amount);
   176	                    self.add_available(&amount);
   177	                    self.handled_disputes.insert(tx);
   178	
   179	                    Ok(())
   180	                }
   181	                Some(FundsTransaction::Withdrawal { amount }) => {
   182	                    /*
   183	                    Reject dispute of `Withdrawal` transaction, subtract `amount` from `held`.
   184	                    */
   185	                    self.subtract_held(&amount);
   186	                    self.handled_disputes.insert(tx);
   187	
   188	                    Ok(())
   189	                }
   190	                None => Err(ClientError::InvalidTransaction),
   191	            },
   192	            Transaction::Chargeback { tx, .. } => match self.disputes.remove(&tx) {
   193	                Some(FundsTransaction::Deposit { amount }) => {
   194	                    /*
   195	                    Reverse `Deposit` transaction, subtract `amount` from `held`.
   196	                    */
   197	                    self.subtract_held(&amount);
   198	                    self.handled_disputes.insert(tx);
   199	                    self.locked = true;
   200	
   201	                    Ok(())
   202	                }
   203	                Some(FundsTransaction::Withdrawal { amount }) => {
   204	                    /*
   205	                    Reverse of `Withdrawal` transaction, move `amount` from `held` to `available`.
   206	                    */
   207	                    self.subtract_held(&amount);
   208	                    self.add_available(&amount);
   209	                    self.handled_disputes.insert(tx);
   210	                    self.locked = true;
   211	
   212	                    Ok(())
   213	                }
   214	                None => Err(ClientError::InvalidTransaction),
   215	            },
   216	        }
   217	    }
