  1	use std::collections::{HashMap, HashSet};
  2	use std::fmt;
  3	
  4	use rust_decimal::Decimal;
  5	use serde::ser::{Serialize, SerializeStruct, Serializer};
  6	
  7	use crate::engine::{INDEX_SIZE, Index};
  8	use crate::transaction::Transaction;
  9	
 10	// Subset of `Transaction` holding only the funds-moving variants, used to
 11	// remember transaction history for `Dispute`/`Resolve`/`Chargeback` lookups.
 12	// Internal to `Client` — never exposed outside this module.
 13	#[derive(Debug)]
 14	enum FundsTransaction {
 15	    Deposit { amount: Decimal },
 16	    Withdrawal { amount: Decimal },
 17	}
 18	
 19	#[derive(Debug)]
 20	pub enum ClientError {
 21	    AccountLocked,
 22	    IncorrectIndex,
 23	    InsufficientFunds,
 24	    InvalidTransaction,
 25	    TransactionReferenceConflict,
 26	}
 27	
 28	impl fmt::Display for ClientError {
 29	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
 30	        match self {
 31	            ClientError::AccountLocked => write!(f, "account is locked"),
 32	            ClientError::IncorrectIndex => write!(f, "incorrect transaction index"),
 33	            ClientError::InsufficientFunds => write!(f, "insufficient available funds"),
 34	            ClientError::InvalidTransaction => write!(f, "invalid transaction"),
 35	            ClientError::TransactionReferenceConflict => {
 36	                write!(f, "transaction identifier conflict")
 37	            }
 38	        }
 39	    }
 40	}
 41	
 42	impl std::error::Error for ClientError {}
 43	
 44	pub struct Client {
 45	    pub client_id: u16,
 46	    pub available: Decimal,
 47	    pub held: Decimal,
 48	    pub locked: bool,
 49	    // holds `Deposit` and `Withdrawal` transaction history
 50	    transactions: HashMap<u32, FundsTransaction>,
 51	    // holds disputed `Deposit` and `Withdrawal` transactions
 52	    disputes: HashMap<u32, FundsTransaction>,
 53	    // holds resolved or chargebacked txs to detect tx conflict
 54	    handled_disputes: HashSet<u32>,
 55	}
 56	
 57	impl Serialize for Client {
 58	    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
 59	    where
 60	        S: Serializer,
 61	    {
 62	        let mut state = serializer.serialize_struct("Client", 5)?;
 63	        state.serialize_field("client", &self.client_id)?;
 64	        state.serialize_field("available", &self.available)?;
 65	        state.serialize_field("held", &self.held)?;
 66	        state.serialize_field("total", &(self.available + self.held))?;
 67	        state.serialize_field("locked", &self.locked)?;
 68	        state.end()
 69	    }
 70	}
 71	
 72	impl Client {
 73	    pub fn new(client_id: u16) -> Self {
 74	        Client {
 75	            client_id,
 76	            available: Decimal::ZERO,
 77	            held: Decimal::ZERO,
 78	            locked: false,
 79	            transactions: HashMap::new(),
 80	            disputes: HashMap::new(),
 81	            handled_disputes: HashSet::new(),
 82	        }
 83	    }
 84	
 85	    fn add_available(&mut self, amount: &Decimal) {
 86	        self.available = (self.available + amount).round_dp(4);
 87	    }
 88	
 89	    fn subtract_available(&mut self, amount: &Decimal) {
 90	        self.available = (self.available - amount).round_dp(4);
 91	    }
 92	
 93	    fn add_held(&mut self, amount: &Decimal) {
 94	        self.held = (self.held + amount).round_dp(4);
 95	    }
 96	
 97	    fn subtract_held(&mut self, amount: &Decimal) {
 98	        self.held = (self.held - amount).round_dp(4);
 99	    }
100	
101	    fn get_index_mmap_value(index_mmap: &mut memmap2::MmapMut, key: usize) -> Result<Index, ()> {
102	        let bytes: [u8; 8] = index_mmap[key * INDEX_SIZE..key * INDEX_SIZE + INDEX_SIZE]
103	            .try_into()
104	            .unwrap();
105	
106	        Ok(Index::from_le_bytes(bytes))
107	    }
108	
109	    fn is_tx_in_conflict(&self, tx: &u32, index_mmap: &mut memmap2::MmapMut) -> bool {
110	        self.transactions.contains_key(&tx)
111	            || self.disputes.contains_key(&tx)
112	            || self.handled_disputes.contains(&tx)
113	    }
114	
115	    pub fn process_transaction(
116	        &mut self,
117	        transaction: Transaction,
118	        index_mmap: &mut memmap2::MmapMut,
119	    ) -> Result<(), ClientError> {
120	        match transaction {
121	            Transaction::Deposit { .. } | Transaction::Withdrawal { .. } if self.locked => {
122	                /*
123	                Client has locked account.
124	                */
125	                Err(ClientError::AccountLocked)
126	            }
127	            Transaction::Deposit { tx, .. } | Transaction::Withdrawal { tx, .. }
128	                if self.is_tx_in_conflict(&tx) =>
129	            {
130	                /*
131	                Transaction identifier detected.
132	                */
133	                Err(ClientError::TransactionReferenceConflict)
134	            }
135	            Transaction::Withdrawal { amount, .. } if self.available < amount => {
136	                /*
137	                Client has no funds for withdrawal.
138	                */
139	                Err(ClientError::InsufficientFunds)
140	            }
141	            Transaction::Deposit { tx, amount, .. } => {
142	                /*
143	                Add `amount` to available deposit.
144	                */
145	                self.add_available(&amount);
146	                self.transactions
147	                    .insert(tx, FundsTransaction::Deposit { amount });
148	                Ok(())
149	            }
150	
151	            Transaction::Withdrawal { tx, amount, .. } => {
152	                /*
153	                Withdraw `amount` from available deposit.
154	                */
155	                self.subtract_available(&amount);
156	                self.transactions
157	                    .insert(tx, FundsTransaction::Withdrawal { amount });
158	                Ok(())
159	            }
160	
161	            Transaction::Dispute { tx, .. } => match self.transactions.remove(&tx) {
162	                Some(FundsTransaction::Deposit { amount }) => {
163	                    /*
164	                    Dispute to `Deposit` transaction, move `amount` from `available` to `held`.
165	                    */
166	                    self.add_held(&amount);
167	                    self.subtract_available(&amount);
168	
169	                    self.disputes
170	                        .insert(tx, FundsTransaction::Deposit { amount });
171	                    Ok(())
172	                }
173	                Some(FundsTransaction::Withdrawal { amount }) => {
174	                    /*
175	                    Dispute to `Withdrawal` transaction, add `amount` to `held`.
176	                    */
177	                    self.add_held(&amount);
178	
179	                    self.disputes
180	                        .insert(tx, FundsTransaction::Withdrawal { amount });
181	                    Ok(())
182	                }
183	                None => Err(ClientError::InvalidTransaction),
184	            },
185	            Transaction::Resolve { tx, .. } => match self.disputes.remove(&tx) {
186	                Some(FundsTransaction::Deposit { amount }) => {
187	                    /*
188	                    Reject dispute of `Deposit` transaction, move `amount` from `held` to `available` .
189	                    */
190	                    self.subtract_held(&amount);
191	                    self.add_available(&amount);
192	                    self.handled_disputes.insert(tx);
193	
194	                    Ok(())
195	                }
196	                Some(FundsTransaction::Withdrawal { amount }) => {
197	                    /*
198	                    Reject dispute of `Withdrawal` transaction, subtract `amount` from `held`.
199	                    */
200	                    self.subtract_held(&amount);
201	                    self.handled_disputes.insert(tx);
202	
203	                    Ok(())
204	                }
205	                None => Err(ClientError::InvalidTransaction),
206	            },
207	            Transaction::Chargeback { tx, .. } => match self.disputes.remove(&tx) {
208	                Some(FundsTransaction::Deposit { amount }) => {
209	                    /*
210	                    Reverse `Deposit` transaction, subtract `amount` from `held`.
211	                    */
212	                    self.subtract_held(&amount);
213	                    self.handled_disputes.insert(tx);
214	                    self.locked = true;
215	
216	                    Ok(())
217	                }
218	                Some(FundsTransaction::Withdrawal { amount }) => {
219	                    /*
220	                    Reverse of `Withdrawal` transaction, move `amount` from `held` to `available`.
221	                    */
222	                    self.subtract_held(&amount);
223	                    self.add_available(&amount);
224	                    self.handled_disputes.insert(tx);
225	                    self.locked = true;
226	
227	                    Ok(())
228	                }
229	                None => Err(ClientError::InvalidTransaction),
230	            },
231	        }
232	    }
233	}

