use std::collections::HashMap;
use std::fs::File;
use std::io;

use memmap2::MmapMut;
use tempfile::tempfile;

use crate::client::{Client, ClientError};
use crate::transaction::Transaction;

pub type Index = u64;

// 2^32 different client ids
const INDEX_COUNT: u64 = 1 << 32;
pub const INDEX_SIZE: usize = std::mem::size_of::<Index>();
const TOTAL_SIZE: u64 = INDEX_COUNT * (INDEX_SIZE as u64);

// Backs the transaction index with a memory-mapped temporary file, so large
// input files don't need their index kept fully in memory.
struct IndexBuffer {
    file: File,
    mmap: MmapMut,
}

impl IndexBuffer {
    fn new() -> io::Result<Self> {
        let file = tempfile()?;
        file.set_len(TOTAL_SIZE)?;
        let mmap = unsafe { MmapMut::map_mut(&file)? };

        Ok(IndexBuffer { file, mmap })
    }
}

pub struct TransactionEngine {
    pub clients: HashMap<u16, Client>,
    index: IndexBuffer,
}

impl TransactionEngine {
    pub fn new() -> io::Result<Self> {
        Ok(TransactionEngine {
            clients: HashMap::new(),
            index: IndexBuffer::new()?,
        })
    }

    pub fn process_transaction(&mut self, transaction: Transaction) -> Result<(), ClientError> {
        let client_id = transaction.client_id();
        let client = self
            .clients
            .entry(client_id)
            .or_insert_with(|| Client::new(client_id));
        client.process_transaction(transaction, &mut self.index.mmap)
    }
}

