use std::collections::HashMap;
use std::env;
use std::error::Error;
use std::fs::File;
use std::io;
use std::path::Path;
use std::process::ExitCode;

use memmap2::Mmap;

use k_exercise::client::Client;
use k_exercise::engine::TransactionEngine;
use k_exercise::record::Record;
use k_exercise::transaction::Transaction;

const HEADER_COLUMNS: [&str; 4] = ["type", "client", "tx", "amount"];

/// Memory-maps the input file and validates that its first line is a header
/// row with exactly the expected column names (`type,client,tx,amount`).
/// Returns the mapping together with the byte offset where the first data
/// record starts, i.e. right after the header line.
fn mmap_input_file(path: &str) -> io::Result<(Mmap, usize)> {
    let file = File::open(path)?;
    let mmap = unsafe { Mmap::map(&file)? };

    let header_end = mmap
        .iter()
        .position(|&b| b == b'\n')
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "missing header row"))?;

    let header_line = mmap[..header_end]
        .strip_suffix(b"\r")
        .unwrap_or(&mmap[..header_end]);
    let header = String::from_utf8_lossy(header_line);
    let columns: Vec<&str> = header.split(',').map(str::trim).collect();

    if columns != HEADER_COLUMNS {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            format!("unexpected header columns: '{header}'"),
        ));
    }

    Ok((mmap, header_end + 1))
}

fn write_clients(clients: &HashMap<u16, Client>) -> Result<(), Box<dyn Error>> {
    let mut writer = csv::Writer::from_writer(io::stdout());
    for client in clients.values() {
        writer.serialize(client)?;
    }
    writer.flush()?;
    Ok(())
}

fn print_usage(program: &str) {
    eprintln!("Usage: {program} <input.csv>");
    eprintln!("  <input.csv>    path to a CSV file containing transactions");
}

fn main() -> ExitCode {
    let args: Vec<String> = env::args().collect();

    if args.len() != 2 {
        print_usage(&args[0]);
        return ExitCode::FAILURE;
    }

    let path = &args[1];
    if !Path::new(path).exists() {
        eprintln!("error: file '{path}' does not exist");
        return ExitCode::FAILURE;
    }

    let records = match load_records(path) {
        Ok(records) => records,
        Err(e) => {
            eprintln!("error: failed to parse CSV file '{path}': {e}");
            return ExitCode::FAILURE;
        }
    };

    let mut engine = match TransactionEngine::new() {
        Ok(engine) => engine,
        Err(e) => {
            eprintln!("error: IO error: {e}");
            return ExitCode::FAILURE;
        }
    };

    for record in records {
        let record = match record {
            Ok(r) => r,
            Err(e) => {
                eprintln!("error: failed to parse record: {e}");
                continue;
            }
        };
        let transanction = match Transaction::try_from(&record) {
            Ok(v) => v,
            Err(e) => {
                // ignore invalid records
                eprintln!("error: cannot parse transaction from record '{record}': {e}");
                continue;
            }
        };
        if let Err(e) = engine.process_transaction(transanction) {
            // proccesing transaction failed
            eprintln!("error: invalid transaction: {e}");
        }
    }

    if let Err(e) = write_clients(&engine.clients) {
        eprintln!("error: failed to write CSV output: {e}");
        return ExitCode::FAILURE;
    }

    ExitCode::SUCCESS
}

