        let original = fs::read_to_string(path).unwrap();
        println!("--- original ---\n{original}");

        let mut parser = MmapRecordParser::new(path).unwrap();
        let offset = parser.first_record_offset();
        println!("first_record_offset = {offset}");

        let record = parser.try_read_record(offset).unwrap().unwrap();
