            return false;
        };

        let field_offset = {
            let Some((line, _)) = self.line_at(offset) else {
                return false;
            };
            match field_start_offset(line, type_index) {
                Some(field_offset) if field_offset < line.len() => field_offset,
                _ => return false,
            }
