#[cfg(test)]
mod scratch_next_check {
    use super::*;

    #[test]
    fn scratch_next() {
        let path = "/tmp/k-exercise-scratch/next_test.csv";
        let mut parser = MmapRecordParser::new(path).unwrap();

        let mut seen = Vec::new();
        while let Some((offset, result)) = parser.next() {
            let record = result.unwrap();
            println!("offset={offset} record={record:?}");
            seen.push((offset, record.r#type.clone()));

