        let r1 = parser.try_read_record(seen[1].0).unwrap().unwrap();
        let r2 = parser.try_read_record(seen[2].0).unwrap().unwrap();
        println!("after mutation: {r0:?} {r1:?} {r2:?}");
        assert_eq!(r0.r#type, "Xeposit");
        assert_eq!(r1.r#type, "Xeposit");
        assert_eq!(r2.r#type, "withdrawal");
    }
}
