mod scratch_next_check {
    use super::*;

    #[test]
    fn scratch_next() {
        let path = "/tmp/k-exercise-scratch/next_test.csv";
        let mut parser = MmapRecordParser::new(path).unwrap();

        let mut seen = Vec::new();
        while let Some((offset, result)) = parser.next() {
            let record = result.unwrap();
            println!("offset={offset} record={record:?}");
            seen.push((offset, record.r#type.clone()));

            if record.r#type == "deposit" {
                let ok = parser.set_type_first_byte(offset, b'X');
                assert!(ok, "expected mutation to succeed for offset {offset}");
            }
        }

        assert_eq!(seen.len(), 3);
        // blank line was skipped, and all 3 real records were visited in order
        assert_eq!(seen[0].1, "deposit");
        assert_eq!(seen[1].1, "deposit");
        assert_eq!(seen[2].1, "withdrawal");

        // next() correctly reports end of file
        assert!(parser.next().is_none());

        // re-read: the two deposits should now read back as mutated "Xeposit"
        let r0 = parser.try_read_record(seen[0].0).unwrap().unwrap();
        let r1 = parser.try_read_record(seen[1].0).unwrap().unwrap();
        let r2 = parser.try_read_record(seen[2].0).unwrap().unwrap();
        println!("after mutation: {r0:?} {r1:?} {r2:?}");
        assert_eq!(r0.r#type, "Xeposit");
        assert_eq!(r1.r#type, "Xeposit");
        assert_eq!(r2.r#type, "withdrawal");
    }
}

