    19	/// Memory-maps the input file and validates that its first line is a header
    20	/// row containing exactly the expected column names (`type`, `client`,
    21	/// `tx`, `amount`) — in any order. Returns the mapping together with that
    22	/// header (for name-based per-record field mapping) and the byte offset
    23	/// where the first data record starts, i.e. right after the header line.
    24	fn mmap_input_file(path: &str) -> io::Result<(Mmap, csv::ByteRecord, usize)> {
    25	    let file = File::open(path)?;
    26	    let mmap = unsafe { Mmap::map(&file)? };
    27	
    28	    let header_end = mmap
    29	        .iter()
    30	        .position(|&b| b == b'\n')
    31	        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidData, "missing header row"))?;
    32	
    33	    let header_line = mmap[..header_end]
    34	        .strip_suffix(b"\r")
    35	        .unwrap_or(&mmap[..header_end]);
    36	    let header = String::from_utf8_lossy(header_line);
    37	    let columns: Vec<&str> = header.split(',').map(str::trim).collect();
    38	
    39	    let mut sorted_columns = columns.clone();
    40	    sorted_columns.sort_unstable();
    41	    let mut expected_columns = HEADER_COLUMNS;
    42	    expected_columns.sort_unstable();
    43	
    44	    if sorted_columns != expected_columns {
    45	        return Err(io::Error::new(
    46	            io::ErrorKind::InvalidData,
    47	            format!("unexpected header columns: '{header}'"),
    48	        ));
    49	    }
    50	
    51	    let headers: csv::ByteRecord = columns.into_iter().collect();
    52	
    53	    Ok((mmap, headers, header_end + 1))
    54	}
