    10	use crate::transaction::Transaction;
    11	
    12	pub type Index = usize;
    13	
    14	// 2^32 different client ids
    15	const INDEX_COUNT: u64 = 1 << 32;
    16	pub const INDEX_SIZE: usize = std::mem::size_of::<Index>();
    17	const TOTAL_SIZE: u64 = INDEX_COUNT * (INDEX_SIZE as u64);
    18	
    19	// Backs the transaction index with a memory-mapped temporary file, so large
    20	// input files don't need their index kept fully in memory.
    21	pub struct IndexBuffer {
    22	    file: File,
    23	    mmap: MmapMut,
    24	    // byte length of `file`/`mmap`, used to bounds-check `key` in `get`/`set`
    25	    size: u64,
    26	}
    27	
    28	impl IndexBuffer {
    29	    fn new() -> io::Result<Self> {
    30	        let file = tempfile()?;
    31	        file.set_len(TOTAL_SIZE)?;
    32	        let mmap = unsafe { MmapMut::map_mut(&file)? };
    33	
    34	        Ok(IndexBuffer {
    35	            file,
    36	            mmap,
    37	            size: TOTAL_SIZE,
    38	        })
    39	    }
    40	
    41	    /// Decodes the little-endian `Index` value stored for `key`, or `None`
    42	    /// if `key` falls outside the buffer.
    43	    pub fn get(&self, key: u32) -> Option<Index> {
    44	        let offset = key as u64 * INDEX_SIZE as u64;
    45	        if offset + INDEX_SIZE as u64 > self.size {
    46	            return None;
    47	        }
    48	
    49	        let offset = offset as usize;
    50	        let bytes: [u8; INDEX_SIZE] = self.mmap[offset..offset + INDEX_SIZE].try_into().unwrap();
    51	        Some(Index::from_le_bytes(bytes))
    52	    }
    53	
    54	    /// Encodes `value` as little-endian bytes at `key`'s position. Returns
    55	    /// `false` without writing anything if `key` falls outside the buffer.
    56	    pub fn set(&mut self, key: u32, value: Index) -> bool {
    57	        let offset = key as u64 * INDEX_SIZE as u64;
    58	        if offset + INDEX_SIZE as u64 > self.size {
    59	            return false;
    60	        }
    61	
    62	        let offset = offset as usize;
    63	        self.mmap[offset..offset + INDEX_SIZE].copy_from_slice(&value.to_le_bytes());
    64	        true
    65	    }
    66	}
    67	
    68	pub struct TransactionEngine {
    69	    pub clients: HashMap<u16, Client>,
    70	    index: IndexBuffer,
    71	}
    72	
    73	impl TransactionEngine {
    74	    pub fn new() -> io::Result<Self> {
    75	        Ok(TransactionEngine {
    76	            clients: HashMap::new(),
    77	            index: IndexBuffer::new()?,
    78	        })
    79	    }
    80	
    81	    pub fn process_transaction(
    82	        &mut self,
    83	        transaction: Transaction,
    84	        tx_offset: Index,
    85	        input_file: &mut MmapRecordParser,
    86	    ) -> Result<(), ClientError> {
    87	        let client_id = transaction.client_id();
    88	        let client = self
    89	            .clients
    90	            .entry(client_id)
    91	            .or_insert_with(|| Client::new(client_id));
    92	        client.process_transaction(transaction, tx_offset, &mut self.index, input_file)
    93	    }
    94	}
