                        self.add_available(&amount);
                        self.locked = true;
                        if !index_mmap.set(tx, 0) {
                            return Err(ClientError::IncorrectIndex);
                        }
                        Ok(())
                    }
                    _ => Err(ClientError::InvalidTransaction),
                }
            }
        }
    }
}

